# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"f2ff9a1f06a88b01621b7ae906ef0211290d1c8a168a15542486a8f61c0833b9"}\n' > "${dest}/.cargo-checksum.json"
